/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// Inserts one row per XAPI_APIS enum value that doesn't already have a row,
/// so every API is visible in the XAPI_ExecuteScripts form without requiring
/// the user to add rows manually. Description is copied from the matching
/// XAPI_APIConfigurations row - on insert, and to backfill any existing row
/// whose Description is still blank.
/// </summary>
public static void ensureAllApisExist()
{
    SysDictEnum             dictEnum = new SysDictEnum(enumNum(XAPI_APIS));
    XAPI_ExecuteScripts     scripts;
    XAPI_APIConfigurations  apiConfig;
    XAPI_APIS               api;
    int                     i;

    for (i = 0; i < dictEnum.values(); i++)
    {
        api = dictEnum.index2Value(i);

        select firstonly apiConfig
            where apiConfig.API == api;

        select firstonly scripts
            where scripts.APIName == api;

        if (!scripts.RecId)
        {
            scripts.clear();
            scripts.APIName    = api;
            scripts.Description = apiConfig.Description;
            scripts.insert();
        }
        else if (!scripts.Description && apiConfig.Description)
        {
            ttsbegin;
            scripts.selectForUpdate(true);
            scripts.Description = apiConfig.Description;
            scripts.update();
            ttscommit;
        }
    }
}
